-- Payment-led recovery metrics; label denominator as current account snapshot proxy.
SELECT DATE_TRUNC('month',event_at_source)::date month_start,SUM(amount) FILTER(WHERE payment_status='SUCCESS' AND amount>0) gross_success_inr,COUNT(DISTINCT account_id) FILTER(WHERE payment_status='SUCCESS' AND amount>0) paying_accounts,COUNT(DISTINCT account_id) FILTER(WHERE payment_status='REVERSED') reversed_accounts,COUNT(*) FILTER(WHERE payment_status='REVERSED') reversal_rows FROM clean.payments_exact_dedup GROUP BY 1 ORDER BY 1;
-- Contact proxy: answered call records / all call records. Not RPC without a verified person-level contact disposition.
SELECT DATE_TRUNC('month',event_at::timestamp)::date month_start,COUNT(*) call_rows,COUNT(*) FILTER(WHERE UPPER(call_status)='ANSWERED') answered_rows,COUNT(*) FILTER(WHERE UPPER(call_status)='ANSWERED')::numeric/NULLIF(COUNT(*),0) answered_call_rate FROM raw.calls GROUP BY 1 ORDER BY 1;
-- PTP kept rate: status-level proxy; censor OPEN and do not call it matured until promised_date passes.
SELECT DATE_TRUNC('month',event_at::timestamp)::date month_start,COUNT(*) FILTER(WHERE UPPER(status)='KEPT') kept,COUNT(*) FILTER(WHERE UPPER(status) IN ('KEPT','BROKEN')) matured_ptps,COUNT(*) FILTER(WHERE UPPER(status)='KEPT')::numeric/NULLIF(COUNT(*) FILTER(WHERE UPPER(status) IN ('KEPT','BROKEN')),0) kept_rate_among_resolved FROM raw.promises_to_pay GROUP BY 1 ORDER BY 1;
